<script setup lang="ts">
const api=useApi(); const { data: rentals, refresh }=await useAsyncData('admin-rentals',()=>api.request<any[]>('/admin/rentals').catch(()=>[]))
async function setStatus(id:string,status:string){await api.request(`/admin/rentals/${id}/status`,{method:'POST',body:{status}});await refresh()}
</script>
<template><div><div class="mb-5"><p class="label-mono text-signal-deep">HaaS</p><h1 class="mt-1 font-display text-[clamp(2.2rem,3vw,2.7rem)] font-semibold tracking-[-.045em]">Rentals.</h1><p class="mt-1 text-[11.5px] text-ink/45">Kit reservations, deposits and return status.</p></div><div class="a-card overflow-hidden"><table class="w-full text-left text-[11px]"><thead class="border-b border-ink/10 bg-paper"><tr class="font-mono text-[7.5px] uppercase tracking-[.08em] text-ink/35"><th class="px-4 py-2.5">Ref</th><th class="px-4 py-2.5">Kit</th><th class="px-4 py-2.5">Window</th><th class="px-4 py-2.5">Total</th><th class="px-4 py-2.5">Deposit</th><th class="px-4 py-2.5">Status</th></tr></thead><tbody><tr v-for="r in rentals" :key="r._id" class="border-t border-ink/10"><td class="px-4 py-3 font-mono text-[9px]">{{ r.ref }}</td><td class="px-4 py-3">{{ r.productName }}</td><td class="px-4 py-3">{{ shortDate(r.from) }} → {{ shortDate(r.to) }}</td><td class="px-4 py-3">{{ money(r.total) }}</td><td class="px-4 py-3 text-ink/45">{{ money(r.deposit) }}</td><td class="px-4 py-3"><AppSelect :model-value="r.status" :options="['reserved','active','returned','cancelled']" compact aria-label="Rental status" @update:model-value="v => setStatus(r._id, String(v))" /></td></tr></tbody></table></div></div></template>
